	// Double Soft 15 (A,4) vs Dealer 5
	hSoft15 := engine.NewHand(10)
	hSoft15.AddCard(cards.NewCard(cards.Ace, cards.Hearts))
	hSoft15.AddCard(cards.NewCard(cards.Four, cards.Spades))
