	noDasRule := rules.VegasStrip()
	noDasRule.DoubleAfterSplit = false
	advNoDas := NewStrategyAdvisor(noDasRule)
	rec = advNoDas.Advise(h6s, cards.NewCard(cards.Two, cards.Clubs), 0)
