	if rec.Action != engine.ActionSplit {
		t.Errorf("2s vs 5 should split, got %s", rec.Action)
	}

	// Pair 10s -> Stand
	h10s := engine.NewHand(10)
	h10s.AddCard(cards.NewCard(cards.Ten, cards.Hearts))
	h10s.AddCard(cards.NewCard(cards.Ten, cards.Spades))
