func main() {
	if len(os.Args) > 1 && os.Args[1] == "sim" {
		runSimulation()
		return
	}

	runInteractiveLoop()
}

func runSimulation() {
	fmt.Println("=== 🔮 Blackjack Monte Carlo Oracle Simulator ===")

	// Create simulation configuration
	config := simulation.SimConfig{
		HandsToPlay:     100_000,
		Workers:         8,
		Rules:           rules.VegasStrip(),
		CountingSystem:  oracle.HiLo,
		BaseBet:         10.0,
		UseCardCounting: true,
	}

	fmt.Printf("Rules: %s\n", config.Rules.Name)
	fmt.Printf("Hands: %d\n", config.HandsToPlay)
	fmt.Printf("Counting System: %s\n", config.CountingSystem)
	fmt.Printf("Card Counting Active: %v\n", config.UseCardCounting)
	fmt.Println("Starting simulation...\n")

	sim := simulation.NewSimulator(config)

	startTime := time.Now()
	stats, err := sim.Run(context.Background(), nil)
	if err != nil {
		fmt.Printf("Simulation failed: %v\n", err)
		return
	}
	elapsed := time.Since(startTime)

	fmt.Printf("=====================================\n")
	fmt.Printf("Simulation completed in %v\n", elapsed)
	fmt.Printf("Speed: %.0f hands/sec\n", float64(stats.HandsPlayed)/elapsed.Seconds())
	fmt.Printf("Hands Played: %d\n", stats.HandsPlayed)
	fmt.Printf("Hands Won: %d (%.2f%%)\n", stats.HandsWon, float64(stats.HandsWon)/float64(stats.HandsPlayed)*100)
	fmt.Printf("Hands Lost: %d (%.2f%%)\n", stats.HandsLost, float64(stats.HandsLost)/float64(stats.HandsPlayed)*100)
	fmt.Printf("Hands Pushed: %d (%.2f%%)\n", stats.HandsPushed, float64(stats.HandsPushed)/float64(stats.HandsPlayed)*100)
	fmt.Printf("Total Amount Wagered: $%.2f\n", stats.TotalWagered)
	fmt.Printf("Net Profit/Loss: $%.2f\n", stats.NetProfit)
	fmt.Printf("Player Edge/EV: %.4f%%\n", stats.PlayerEdge*100)
	fmt.Printf("=====================================\n")
}

func runInteractiveLoop() {
	scanner := bufio.NewScanner(os.Stdin)
	renderer := ui.NewCardRenderer(true)

	ruleSet := rules.VegasStrip()
	shoe := cards.NewShoe(ruleSet.Decks)
